<script>
import DataService from '../../services/DataService';
import AvailableContract from '../Biller/AvailableContract.vue';
import AvailableBiller from '../Biller/AvailableBiller.vue';

export default {
    components: {
        AvailableContract,
        AvailableBiller
    },
    props: {
        GroupBy: {
            type: String,
            required: false,
        },
        editPayload:{
            type:Object,
            required: false,
        },
        isEditJsonData: {
            type: Boolean,
            required: false
        },        
    },
    computed: {
        allRowsSelected() {
            if (this.receivedData.length === 0) return false;
            return this.receivedData.every(row => row.selected === true);
        },
        someRowsSelected() {
            return this.receivedData.some(row => row.selected === true);
        },
        /** Assign Contract: "Select Billers (n)". Assign Biller: "Selected Contracts (n)". */
        assignmentSectionTitle() {
            const n = Array.isArray(this.receivedData) ? this.receivedData.length : 0;
            if (this.GroupBy === 'Contract') {
                const k = this.$t('SelectedBillers');
                const base = k && k !== 'SelectedBillers' ? k : 'Selected Billers';
                return `${base} (${n})`;
            }
            const k = this.$t('SelectedContracts');
            const base = k && k !== 'SelectedContracts' ? k : 'Selected Contracts';
            return `${base} (${n})`;
        },
        /** Assign Contract: billers already on the grid — hidden in Add Biller until the row is removed */
        assignedBillerIdsForPopup() {
            if (this.GroupBy !== 'Contract') return [];
            // Must use receivedDataMaster (full list) not receivedData (search-filtered view)
            // Otherwise assigned billers hidden by search would reappear as available in the popup
            const ids = this.receivedDataMaster
                .map(r => Number(r.billerId))
                .filter(id => !isNaN(id) && id > 0);
            return [...new Set(ids)];
        },
        /** Assign Biller: contracts already on the grid — hidden in Add Contracts until the row is removed */
        assignedContractIdsForPopup() {
            if (this.GroupBy !== 'Biller') return [];
            // Must use receivedDataMaster (full list) not receivedData (search-filtered view)
            // Otherwise assigned contracts hidden by search would reappear as available in the popup
            const ids = this.receivedDataMaster
                .map(r => Number(r.clientId))
                .filter(id => !isNaN(id) && id > 0);
            return [...new Set(ids)];
        },
        /** Single biller id for the contracts API when opening Add Contracts */
        billerIdForContractPicker() {
            const v = this.FormSchema?.[0]?.Data?.[0]?.value;
            if (Array.isArray(v) && v.length) {
                const n = Number(v[0]);
                return isNaN(n) ? 0 : n;
            }
            if (v != null && v !== '') {
                const n = Number(v);
                return isNaN(n) ? 0 : n;
            }
            const b = this.billerId;
            if (Array.isArray(b) && b.length) {
                const n = Number(b[0]);
                return isNaN(n) ? 0 : n;
            }
            return Number(b) || 0;
        },

        allFlag: {            
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isFlag === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isFlag = value;
                });
            }
        },

        allInvoice: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isInvoice === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isInvoice = value;
                });
            }
        },

        allUnprocess: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isUnprocess === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isUnprocess = value;
                });
            }
        },

        allBilledUnbilled: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isBilledUnbilled === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isBilledUnbilled = value;
                });
            }
        },

        allRateSchedule: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isRateSchedule === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isRateSchedule = value;
                });
            }
        },

        allBillingRule: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isBillingRule === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isBillingRule = value;
                });
            }
        },

        allReport: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isReport === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isReport = value;
                });
            }
        }
    },
    watch: {
        editPayload: {
            immediate: true,
            handler(payload) {
                if (!payload) return;
                this.GetAssignBillerById(payload.AssignBiller[0]);                
            }
        },
        /** Add mode (Assign Contract): when user picks a contract, load billers for that contract from the API */
        'FormSchema[0].Data[0].value': {
            handler() {
                this.onContractDropdownChanged();
            },
            deep: true
        }
    },
    data() {
        return {
            Loading: false,
            isShown: false,
            companyId: null,
            userId: null,
            isAddContract: false,
            isAddBillerPopup: false,
            ContractBillerListData: [],
            BillerListData: [],
            AssignBillerData: [],
            receivedData: [],
            receivedDataMaster: [],
            deletedItems: [],
            billerId:0,
            Searchtext:'',
            parentBillerid:'',
            _contractBillersDebounceId: null,
            ClientItemsList: [{
                clientId: 0,
                biller: '',
                isFlag: false,
                isInvoice: false,
                isUnprocess: false,
                isBilledUnbilled: false,
                isRateSchedule: false,
                isBillingRule: false,
                isReport: false
            }],
            AvailableContractData: [
                {
                    clientId: 0,
                    contractName: '',
                    checked: false,
                    isFlag: false,
                    isInvoice: false,
                    isUnprocess: false,
                    isBilledUnbilled: false,
                    isRateSchedule: false,
                    isBillingRule: false,
                    isReport: false
                }
            ],

            FormSchema: [{
                layoutType: "triple",
                Data: [
                     {
                            astype: "SearchableSelectField",
                            label: this.GroupBy == 'Contract' ? this.$t('Contract') : this.$t('Biller'),
                            name: "Biller",
                            value: "",
                            placeholder: this.GroupBy == 'Contract' ? this.$t('SearchAndSelectContract') : "Select Biller",
                            visibility: true,
                            isSearch: true,
                            config: {
                                options: [],
                                actionButtons: { selectAll: true,  clear: true },
                                isMultiple: true,
                                itemFields: ['text'],
                                groupFields: ['groupText'],
                                minSearchLength: 0,
                                statusFieldConfig: {
                                    fieldName: 'status',
                                    activeValues: ['Active', 'active'],
                                    inactiveValues: ['Inactive', 'inactive'],
                                    activeColor: '#28a745',
                                    inactiveColor: '#dc3545'
                                },
                                 onChange: null
                            },                            
                            disabled: false,
                            validationRules: {"required": true},
                        }
                        // {
                        //     astype: "SearchableSelectField",
                        //     label: this.$t('Biller'),
                        //     name: "BillerId",
                        //     value: "",
                        //     placeholder: "Select Biller",
                        //     visibility: true,
                        //     isSearch: false,
                        //     config: {
                        //         options: [],
                        //         actionButtons: {
                        //             selectAll: true,
                        //             active: true,
                        //             inactive: true,
                        //             clear: true
                        //         },
                        //         isMultiple: false,
                        //         groupFields: ['groupText'],
                        //         minSearchLength: 0,
                        //         statusFieldConfig: {
                        //             fieldName: 'status',
                        //             activeValues: ['Active', 'active'],
                        //             inactiveValues: ['Inactive', 'inactive'],
                        //             activeColor: '#28a745',
                        //             inactiveColor: '#dc3545'
                        //         },
                        //         onChange: null
                        //     },
                        //     validationRules: {
                        //         "required": true
                        //     },
                        // }


                ]
            }],
            contractData:[]
        }
    },
    mounted() {
        this.$nextTick(() => {
            setTimeout(() => {
                this.isShown = true;
                if (this.GroupBy === 'Contract' && this.isEditJsonData) {
                    this.syncContractDropdownValue();
                }
            }, 50);
        });
    },
    created: async function () {
        var vm = this;
        vm.userId = vm.GetUserInfo.ID;
        vm.companyId = vm.GetUserInfo.CompanyId;
        if(vm.GroupBy == 'Contract'){
            await vm.GetAvailableContracts();
        }
        else{
            await vm.GetBillerList();
        }         
    },
    methods: { 
        stripHtml(s) {
            if (!s) return '';
            return String(s).replace(/<[^>]+>/g, ' ');
        },      
        toggleSelectAll(event) {
            const checked = event.target.checked;
            this.receivedData.forEach(row => {
                row.selected = checked;
            });
        },      
        async GetAvailableContracts() {            
            const vm = this;
            vm.isLoading = true;  
            let SelectedClientList=[];
            const url = `pageNum=&pageSize=1000000&reqFrom=MANAGEBILLER&search=&userId=&screenName=`;
            await DataService.GetAvailableContracts(url).then(response => {
                vm.isLoading = false;
                var ClientList = response.data.result;
                if (ClientList) {
                    var jsondataval = ClientList;
                    if (jsondataval != null) {
                        jsondataval.forEach(item => {
                            let obj = {
                                description: null,
                                displayValue: item.CHILD_NAME,
                                groupText: item.PARENT_NAME,
                                groupValue: null,
                                metaData: null,
                                text: item.CHILD_NAME,
                                value: item.CHILD_USER_ID   
                            };
                            SelectedClientList.push(obj);
                        });
                        const billerField = vm.FormSchema[0].Data.find(f => f.name === 'Biller');
                        if (billerField) {
                            billerField.config.options = SelectedClientList;
                            billerField.config.onChange = () => vm.onContractDropdownChanged();
                        }
                        if (vm.$refs.AssignBiller) {
                            vm.$refs.AssignBiller.updateProperty("Biller", "config.isMultiple", false);
                            vm.$refs.AssignBiller.updateProperty("Biller", "config.options", SelectedClientList);
                            vm.$refs.AssignBiller.UpdateKeyValue();
                        }
                        vm.$nextTick(() => {
                            vm.syncContractDropdownValue();
                        });
                    }
                }
             }).catch(() => {
               vm.isLoading = false;
           });
        },
        syncContractDropdownValue() {
            const vm = this;
            if (vm.GroupBy !== 'Contract' || !vm.isEditJsonData) return;
            const raw = vm.parentBillerid;
            if (raw === null || raw === undefined || raw === '') return;
            let ids = [];
            if (Array.isArray(raw)) {
                ids = raw.map(x => Number(x)).filter(n => !isNaN(n));
            } else if (typeof raw === 'string' && raw.includes(',')) {
                ids = raw.split(',').map(s => Number(s.trim())).filter(n => !isNaN(n));
            } else {
                const n = Number(raw);
                if (!isNaN(n)) ids = [n];
            }
            if (!ids.length) return;
            vm.FormSchema[0].Data[0].value = ids;
            if (vm.$refs.AssignBiller) {
                vm.$refs.AssignBiller.updateProperty("Biller", "value", ids);
                vm.$refs.AssignBiller.UpdateKeyValue();
            }
        },
        rowKey(c) {
            if (this.GroupBy === 'Contract' && c && (c.billerId != null && c.billerId !== '')) {
                return `${c.clientId}_${c.billerId}`;
            }
            return `${c && c.clientId != null ? c.clientId : 'row'}`;
        },
        contractIdForRows() {
            const raw = this.FormSchema?.[0]?.Data?.[0]?.value;
            if (Array.isArray(raw) && raw.length) {
                const n = Number(raw[0]);
                return !isNaN(n) ? n : null;
            }
            const n = Number(raw != null && raw !== '' ? raw : this.parentBillerid);
            return !isNaN(n) ? n : null;
        },
        /** Assign Contract add mode: react to contract single-select and load billers from GetContractBillerList */
        onContractDropdownChanged() {
            if (this._contractBillersDebounceId) {
                clearTimeout(this._contractBillersDebounceId);
            }
            this._contractBillersDebounceId = setTimeout(() => {
                this._contractBillersDebounceId = null;
                this.$nextTick(() => {
                    if (this.GroupBy !== 'Contract' || this.isEditJsonData) return;
                    const cid = this.contractIdForRows();
                    if (!cid || Number(cid) <= 0) {
                        this.receivedData = [];
                        this.receivedDataMaster = [];
                        this.Searchtext = '';
                        return;
                    }
                    this.fetchBillersForSelectedContract(cid);
                });
            }, 150);
        },
        /** Maps GetContractBillerList response to grid rows (Assign Contract / groupBy Contract). */
        buildRowsFromContractBillerApi(resultData, contractId) {
            const cid = contractId != null && contractId !== '' ? Number(contractId) : 0;
            return (resultData || []).map(x => ({
                contractName: x.GroupInfo ? x.GroupInfo : '',
                BillerName: x.GroupInfo ? x.GroupInfo : '',
                clientId: x.ClientId ? x.ClientId : cid,
                billerId: x.GroupId ? x.GroupId : 0,
                selected: false,
                isFlag: x.IsFlag ?? false,
                isInvoice: x.IsInvoice ?? false,
                isUnprocess: x.IsUnprocess ?? false,
                isBilledUnbilled: x.IsBilledUnBilled ?? false,
                isRateSchedule: x.IsRateSchedule ?? false,
                isBillingRule: x.IsBillingRule ?? false,
                isReport: x.IsReport ?? false
            }));
        },
        /** Add mode: load billers already linked to the selected contract from the database */
        async fetchBillersForSelectedContract(contractId) {
            const vm = this;
            const id = Number(contractId);
            if (vm.GroupBy !== 'Contract' || isNaN(id) || id <= 0) return;
            vm.Loading = true;
            try {
                const url = `groupId=${id}&groupBy=${vm.GroupBy}`;
                const response = await DataService.GetContractBillerList(url);
                if (response.status === 200 && response.data?.result) {
                    let resultData = response.data.result;
                    if (typeof resultData === 'string') {
                        resultData = JSON.parse(resultData);
                    }
                    if (!Array.isArray(resultData)) {
                        resultData = resultData ? [resultData] : [];
                    }
                    vm.receivedData = vm.buildRowsFromContractBillerApi(resultData, id);
                    vm.receivedDataMaster = [...vm.receivedData];
                    vm.Searchtext = '';
                } else {
                    vm.receivedData = [];
                    vm.receivedDataMaster = [];
                }
            } catch (e) {
                console.error('fetchBillersForSelectedContract:', e);
                vm.receivedData = [];
                vm.receivedDataMaster = [];
            } finally {
                vm.Loading = false;
            }
        },
        handleAvailableBillerSubmit(payload) {
            const vm = this;
            if (vm.GroupBy !== 'Contract') return;
            vm.Loading = true;
            try {
                const cid = vm.contractIdForRows();
                if (!cid) {
                    vm.ShowAlert(vm.$t('Select') + ' ' + vm.$t('Contract'), 'warning', true);
                    return;
                }
                const list = payload?.AssignBiller;
                if (!list || !list.length) return;
                const newRows = [];
                let skipped = 0;
                for (const item of list) {
                    const numBid = Number(item.USERID);
                    if (isNaN(numBid)) continue;
                    const exists = vm.receivedData.some(r =>
                        Number(r.clientId) === Number(cid) && Number(r.billerId) === numBid
                    );
                    if (exists) {
                        skipped++;
                        continue;
                    }
                    const name = (item.USERNAME || '').toString();
                    newRows.push({
                        clientId: cid,
                        billerId: numBid,
                        contractName: name,
                        BillerName: name,
                        selected: false,
                        isFlag: true,
                        isInvoice: true,
                        isUnprocess: true,
                        isBilledUnbilled: true,
                        isRateSchedule: true,
                        isBillingRule: true,
                        isReport: true
                    });
                }
                if (skipped && !newRows.length) {
                    vm.ShowAlert('Selected billers are already in the list.', 'warning', true);
                    return;
                }
                if (skipped && newRows.length) {
                    vm.ShowAlert('Some billers were skipped because they are already in the list.', 'warning', true);
                }
                vm.mergeReceivedData(newRows);
                vm.isAddBillerPopup = false;
            } finally {
                vm.Loading = false;
            }
        },
        GetBillerList: async function () {
            var vm = this;
            vm.Loading = true;
              try {
                    const url = vm.isEditJsonData ? 'reqFrom=all&moduleName=Billing&IncludeBiller=YES' : `reqFrom=all&moduleName=Billing&IncludeBiller=NO`;
                    const BillerResponse = (await DataService.GetBillerList(url));
                    const BillerResponses=JSON.parse(BillerResponse.data.result)
                    if (BillerResponses) {
                        // vm.$refs.AssignBiller.updateProperty("Biller", "config.options", BillerResponses);
                        // vm.$refs.AssignBiller.UpdateKeyValue();
                    
                        const BillerOptions = BillerResponses.map(item => ({
                            description:  null,
                            displayValue: item.USERNAME,
                            groupText: null,
                            groupValue: null,
                            metaData: item,
                            text: item.USERNAME,     
                            value: item.USERID       
                        }));

                        const billerField = vm.FormSchema[0].Data.find(f => f.name === 'Biller');
                        if (billerField) { billerField.config.options = BillerOptions;}
                        vm.$refs.AssignBiller?.UpdateKeyValue();
                        vm.Loading = false;
                    }
                } catch (error) {
                    console.error('Error loading Biller:', error);
                }
        },

        AddContract() {
            var vm = this;
            if (vm.GroupBy === 'Contract') {
                return;
            }
            const billerValue = vm.FormSchema?.[0]?.Data?.[0]?.value;
            if (!billerValue || (Array.isArray(billerValue) && billerValue.length === 0)) {
                vm.ShowAlert("Please select a Biller", 'warning', true);
                return;
            }
            vm.isAddContract = true;
        },
        AddBillerPopup() {
            var vm = this;
            if (vm.GroupBy !== 'Contract') {
                return;
            }
            const cid = vm.contractIdForRows();
            if (!cid || Number(cid) <= 0) {
                vm.ShowAlert("Please select a Contract", "warning", true);
                return;
            }
            vm.isAddBillerPopup = true;
        },
        async GetAssignBillerById(item){
            var vm=this;
            if(vm.GroupBy=='Contract'){
                vm.FormSchema[0].Data[0].disabled = true;
                // Listing row uses GroupId for the contract when grouped by Contract; ClientIds may be empty
                const contractKey = item.GroupId != null && item.GroupId !== ''
                    ? item.GroupId
                    : item.ClientIds;
                vm.parentBillerid = contractKey;
                vm.$nextTick(() => {
                    vm.syncContractDropdownValue();
                });
                 var url = `groupId=${item.GroupId}&groupBy=${vm.GroupBy}`;                 
                DataService.GetContractBillerList(url).then(response => {
                    if (response.status === 200 && response.data?.result) {
                        let resultData = response.data.result;
                        // If string convert to JSON
                        if (typeof resultData === "string") {
                            resultData = JSON.parse(resultData);
                        }
                        // Ensure array
                        if (!Array.isArray(resultData)) {
                            resultData = [resultData];
                        }
                        vm.receivedData = vm.buildRowsFromContractBillerApi(resultData, item.GroupId);
                        vm.receivedDataMaster = [...vm.receivedData];
                    }
                });
                                
            } 
            else{
                var biller=vm.GroupBy ? vm.GroupBy : 'Biller';
                var url = `groupId=${item.GroupId}&groupBy=${biller}`;
                    await DataService.GetAssignBillerById(url).then(response => {
                      
                    if (response.status === 200 && response.data?.result) {
                        let resultData = response.data.result;
                        
                        if (typeof resultData === "string") {
                            resultData = JSON.parse(resultData);
                        }
                        // 🔥 push API result back into edit payload
                        vm.handleParentCall({
                            AssignBiller: resultData
                        });
                    }
                });
            }           
            
        },

       Delete() {
            const vm = this;
            const selectedItems = vm.receivedData.filter(c => c.selected);

            if (!selectedItems.length) {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"), "warning", true);
                return;
            }

            vm.confirmR(vm.$t("ConfirmDelete"), true, vm.$t("Delete"), function () {
                if (!vm.deletedItems) vm.deletedItems = [];

                selectedItems.forEach(x => {
                    let contractId, billerId;
                    if (vm.GroupBy === "Biller") {
                        // Grouped by Biller: row = contract, biller comes from the selected biller field
                        contractId = x.clientId;
                        billerId = vm.FormSchema[0].Data[0].value;

                        // Handle if biller is multi-select (array)
                        if (Array.isArray(billerId)) {
                            billerId.forEach(bid => {
                                vm.deletedItems.push({
                                    clientId: Number(contractId),
                                    billerId: Number(bid)
                                });
                            });
                            return;
                        }
                    } else {
                        // Grouped by Contract: row shows biller assignment for a contract
                        // From your data pattern: clientId = biller, parentId = contract
                        // contractId = x.parentId || x.contractId || x.clientId;  // contract ID (e.g. 505739)
                        // billerId   = x.clientId || x.billerId;                   // biller ID (e.g. 533971)
                        contractId =  x.clientId || x.parentId || x.contractId || 0;  // contract ID (e.g. 505739)
                        billerId   =  x.billerId || x.clientId || 0;                   // biller ID (e.g. 533971)
                    }

                    if (!contractId || !billerId) {
                        console.warn("Cannot delete - missing IDs in row:", x);
                        return;
                    }

                    vm.deletedItems.push({
                        clientId: Number(contractId),
                        billerId: Number(billerId)
                    });
                });

                // Debug: see what will be sent
                console.log("Items queued for deletion:", JSON.stringify(vm.deletedItems, null, 2));

                // Remove from UI (optimistic update) AND from master so Clear() doesn't restore deleted rows
                vm.receivedData = vm.receivedData.filter(c => !c.selected);
                vm.receivedDataMaster = vm.receivedDataMaster.filter(c => !selectedItems.includes(c));
            });
        },
      
      
       Save() {
            const vm = this;
            const hasDeletes = vm.deletedItems?.length > 0;
            const hasAdds   = vm.receivedDataMaster.length > 0;
            if (!hasDeletes && !hasAdds) {
                vm.ShowAlert([vm.$t("Add") + " " + vm.$t("SelectedContracts")], "warning", true);
                return;
            }
            // Require biller for add mode
            if (hasAdds && !vm.FormSchema?.[0]?.Data?.[0]?.value && vm.GroupBy === "Biller") {
                vm.ShowAlert("Please select Biller", "warning", true);
                return;
            }
            if (hasAdds && vm.GroupBy === "Contract" && !vm.contractIdForRows()) {
                vm.ShowAlert(vm.$t('Select') + ' ' + vm.$t('Contract'), "warning", true);
                return;
            }
            vm.Loading = true;
            const processDeletes = () => {
                if (!hasDeletes) return Promise.resolve();

                const deletePayload = {
                    ClientItemsList: vm.deletedItems.map(item => ({
                        clientId: item.clientId,      // contract
                        billerId: [item.billerId],      // biller
                        isFlag: false,
                        isInvoice: false,
                        isUnprocess: false,
                        isBilledUnbilled: false,
                        isRateSchedule: false,
                        isBillingRule: false,
                        isReport: false
                    })),
                    BillerItemsList: [...new Set(vm.deletedItems.map(d => Number(d.billerId)))],
                    StatusId: 1003,
                    isEditJsonData:  false,
                    groupBy: vm.GroupBy || "Biller"
                };
                console.log("DELETE PAYLOAD:", JSON.stringify(deletePayload, null, 2));

                return DataService.SaveAssignBiller(JSON.stringify(deletePayload))
                    .then(response => {
                        if (response.data?.status !== "Success" && response.data?.Status !== 1) {
                            throw new Error(response.data?.msg || "Delete failed");
                        }
                        return response;
                    });
            };

            const processAdds = () => {
                if (!hasAdds) return Promise.resolve();
                const billerValue = vm.FormSchema?.[0]?.Data?.[0]?.value;
                let addPayload = {}
                if (vm.GroupBy === "Contract") {
                         addPayload = {
                            ClientItemsList: vm.receivedDataMaster.map(c => ({
                                clientId: c.clientId || c.parentId || c.contractId,
                                billerId:  [c.billerId],
                                isFlag: !!c.isFlag,
                                isInvoice: !!c.isInvoice,
                                isUnprocess: !!c.isUnprocess,
                                isBilledUnbilled: !!c.isBilledUnbilled,
                                isRateSchedule: !!c.isRateSchedule,
                                isBillingRule: !!c.isBillingRule,
                                isReport: !!c.isReport
                            })),
                            StatusId: 1001,
                            isEditJsonData: false,
                            groupBy: vm.GroupBy || "Biller"
                        };
                }
                else{                        
                         addPayload = {
                            ClientItemsList: vm.receivedDataMaster.map(c => ({
                                clientId: c.clientId || c.parentId || c.contractId,
                                billerId: Array.isArray(billerValue)
                                    ? billerValue.map(v => Number(v)).filter(v => v > 0)
                                    : billerValue ? [Number(billerValue)] : [],
                                isFlag: !!c.isFlag,
                                isInvoice: !!c.isInvoice,
                                isUnprocess: !!c.isUnprocess,
                                isBilledUnbilled: !!c.isBilledUnbilled,
                                isRateSchedule: !!c.isRateSchedule,
                                isBillingRule: !!c.isBillingRule,
                                isReport: !!c.isReport
                            })),
                            StatusId: 1001,
                            isEditJsonData: false,
                            groupBy: vm.GroupBy || "Biller"
                        };
                    }                 

                console.log("ADD PAYLOAD:", JSON.stringify(addPayload, null, 2));

                return DataService.SaveAssignBiller(JSON.stringify(addPayload))
                    .then(response => {
                        if (response.data?.status !== "Success" && response.data?.Status !== 1) {
                            throw new Error(response.data?.msg || "Save failed");
                        }
                        return response;
                    });
            };

            // Execute sequentially: delete first → then add
            processDeletes()
                .then(() => processAdds())
                .then(() => {
                    vm.ShowAlert((hasDeletes && hasAdds)? vm.$t('UpdatedSuccessfully')
                            : hasDeletes ? vm.$t('DeletedSuccessfully', [vm.$t('Assignment')])
                                : vm.$t('AddedSuccess', [vm.$t('Biller')]),  "success",  true, vm.$t('Alert'));   
                                                   vm.$parent.GetBillerListing();
                    vm.Close();
                })
                .catch(err => {
                    console.error("Batch operation failed:", err);
                    vm.ShowAlert(err.message || "Operation failed (some changes may not have saved)", "danger", true);
                   
                })
                .finally(() => {
                    vm.Loading = false;
                    vm.deletedItems = []; // clear regardless
                });
        },

       SearchButton(txt) {
            const searchTxt = (txt || '').trim().toLowerCase();
            if (!searchTxt) {
                // Empty search = same as Clear
                this.receivedData = this.receivedDataMaster.slice();
                return;
            }
            this.receivedData = this.receivedDataMaster.filter(c => {
                const hay = `${c.contractName || ''} ${c.BillerName || ''}`.trim().toLowerCase();
                return hay.includes(searchTxt);
            });
        },

        Clear() {
            this.Searchtext = '';
            this.receivedData = this.receivedDataMaster.slice();
        },

        Close: function () {
            this.$parent.isAddBiller = false;
        }, 
        
        handleParentCall(payload) {
            const vm = this;
            vm.Loading=true;
            if (!payload?.AssignBiller) return;

            const list = Array.isArray(payload.AssignBiller)
                ? payload.AssignBiller
                : [payload.AssignBiller];

            const parentRecords = list.map(c => ({
                clientId: c.CHILD_USER_ID || c.ClientIds,
                contractName: c.CHILD_NAME || c.GroupInfo || c.GroupName,
                selected: false,
                BillerName:c.BillerName||'',
                isFlag: Boolean(c.IsFlag),
                isInvoice: Boolean(c.IsInvoice),
                isUnprocess: Boolean(c.IsUnprocess),
                isBilledUnbilled: Boolean(c.IsBilledUnBilled ?? c.IsBilledUnbilled),
                isRateSchedule: Boolean(c.IsRateSchedule),
                isBillingRule: Boolean(c.IsBillingRule),
                isReport: Boolean(c.IsReport),

                parentId: c.PARENT_ID || c.GroupId,
                parentName: c.PARENT_NAME || c.GroupInfo
            }));

            // 🔥 SAFE MERGE
            vm.mergeReceivedData(parentRecords);

            vm.AvailableContractData = vm.receivedData;

            //vm.billerId = vm.parentBillerid || list[0]?.GroupId;
            let distinctGroupIds = [...new Set(list.map(x => x.GroupId))];
            vm.billerId = vm.parentBillerid || distinctGroupIds;

            const normalizeArray = v => Array.isArray(v) ? v : v !== null && v !== undefined
                        ? v.toString().split(',').map(Number) : [];

            vm.FormSchema[0].Data[0].value = normalizeArray(vm.billerId);
            vm.FormSchema[0].Data[0].disabled = true;
            vm.Loading = false;
        },

      handleChildSubmit(payload) {
            const vm = this;
            vm.Loading=true;

            if (!payload || !Array.isArray(payload.AssignBiller)) return;

            const childRecords = payload.AssignBiller.map(item => ({
                clientId: item.CHILD_USER_ID,
                contractName: item.CHILD_NAME,
                selected: item.isSelected ?? false,
                BillerName:item.BillerName||'',
                isFlag: true,
                isInvoice: true,
                isUnprocess: true,
                isBilledUnbilled: true,
                isRateSchedule: true,
                isBillingRule: true,
                isReport: true,

                parentId: item.PARENT_ID,
                parentName: item.PARENT_NAME
            }));

            // 🔥 SAFE MERGE
            vm.mergeReceivedData(childRecords);

            vm.AvailableContractData = vm.receivedData;
            vm.isAddContract = false;
            vm.Loading = false;
        },


       mergeReceivedData(newRecords) {
            if (!Array.isArray(this.receivedData)) {
                this.receivedData = [];
            }

            const keyOf = (r) => {
                if (this.GroupBy === 'Contract' && r.billerId != null && r.billerId !== '') {
                    return `${r.clientId}_${r.billerId}`;
                }
                return `${r.clientId}`;
            };

            const map = new Map();
            this.receivedData.forEach(r => {
                map.set(keyOf(r), r);
            });

            newRecords.forEach(r => {
                const key = keyOf(r);
                if (!map.has(key)) {
                    map.set(key, r);
                }
            });

            this.receivedData = Array.from(map.values());
            this.receivedDataMaster = [...this.receivedData];
        },    

    },
}
</script>

